import{_ as t,o as e,c as a,ag as o}from"./chunks/framework.DaAXJYxM.js";const l=JSON.parse('{"title":"第13章 蠢事","description":"","frontmatter":{},"headers":[],"relativePath":"第13章_蠢事.md","filePath":"第13章_蠢事.md"}'),_={name:"第13章_蠢事.md"};function r(n,p,s,u,c,i){return e(),a("div",null,[...p[0]||(p[0]=[o('<h1 id="第13章-蠢事" tabindex="-1">第13章 蠢事 <a class="header-anchor" href="#第13章-蠢事" aria-label="Permalink to &quot;第13章 蠢事&quot;">​</a></h1><p>网课第二个星期，我做了件蠢事。</p><p>事情的起因是一条转发。</p><p>那天中午我在班级群里看到一条记录，是别人转来的，转的是另一个学校的班级群。里面有一段对话，说的是老师布置的作业太多，学生在吐槽。</p><p>我往下划了两下，停住了。</p><p>有一段话很像我认识的一个人说话的方式。短，连着几条，不带标点，中间夹着一个&quot;操&quot;。</p><p>我知道这不可能是她。她们班不在那座城市，而且转发的记录都是别的学校的。</p><p>我往下看了两遍。越看越像。</p><p>那天下午我没有听课。我在网上翻那张转发记录，找它的出处，一层一层往上追。追到下面，找到了一个群的截图，截图上有群名。</p><p>群名是她学校的那种格式。</p><p>我盯着那几个字看了一会儿。世界很小，小到你随手划到的一条转发，背后就是她生活的那座城。</p><p>那天晚上我一直在想这件事。我想她每天面对的那些人都是谁，她的同桌是谁，下课后跟她说话的是谁。她跟我说过的所有事，都像是从很远的地方传过来的回声，我听得到声音，但看不到说话的人。</p><p>我那时候的心情很难说清楚。我不是想找她。我就是想知道，她在另一个城市，跟她说话的那些人，是什么样的人。</p><p>顺着那张截图，我加了一个人。</p><p>那个人是转发的起点之一，我加的时候写的是&quot;同学你好，我想问一个学习上的问题&quot;。这句话是我想了很久才写的，写得像我真的是去问作业的。</p><p>对方通过了。</p><p>我们说了几句话，都是废话。我说我是另一个市的，想问问他们的进度。对方很客气，跟我说了一堆。</p><p>对方问我作业做到哪了，我说做到第三章。他说他们做到第五章了。我说你们好快。他说他们老师抓得紧。</p><p>聊到第五句的时候我差点问了那个问题。我想问，你们班有没有一个说话很冲、爱用短句的人。这句话我打了一半，删了。</p><p>中途对方问了一句：你是哪个班的。</p><p>我报了另一个班。</p><p>对方说，哦，那个班的谁谁谁我认识。</p><p>我说，不认识。</p><p>对方就没再问。</p><p>我以为就这样过去了。</p><p>第二天晚上，她来了。</p><p>她说，你是不是在找人。</p><p>我心里一沉。我说，没有。</p><p>她说，我同学跟我说了。</p><p>她说，有人加他，问了一堆问题，说是别的市的。</p><p>我说，可能不是我。</p><p>她说，他说那个人加他那天，你也在线。</p><p>我盯着屏幕，手指有点凉。</p><p>我说，是我。</p><p>她那边安静了很久。我等着。我脑子里想了很多种她的反应。我以为她会骂我。</p><p>她回的是：你为什么要那样做。</p><p>我说，我就是想看看你那边是什么样子。</p><p>她说，你想看什么。</p><p>我说，我不知道。</p><p>她说，你是不是不信我。</p><p>我说，我信。</p><p>她说，那你还去找。</p><p>我说，我不是去找你。</p><p>她说，那你找谁。</p><p>我答不上来。</p><p>那天的对话停在这里。她过了一会儿又发来一条。</p><p>她说，你不用这样。</p><p>她说，你想问什么，你直接问我。</p><p>我说，那我问。</p><p>她说，你问。</p><p>我打了一行字，删了。</p><p>我本来想问的是：你过得好不好。可这句话太虚了，问出来她大概只会说好。</p><p>我又想问她是不是还有别的人在跟她说话。这句话问出来太难看。</p><p>最后我发出去的是：你最近睡得怎么样。</p><p>她说，还行。</p><p>她说，一点多。</p><p>我说，太晚了。</p><p>她说，习惯了。</p><p>她说，家里那点动静，早睡也睡不着。</p><p>那天晚上我们没再说别的。她十一点半说要下了，比她平时早。我知道她不是困，是不想说了。</p><p>第二天她没有上线。</p><p>第三天也没有。</p><p>第四天她来了，只有一句：我妈今天在家，我不聊了。</p><p>我说好。</p><p>又隔了两天，她说了那件事的最后一句。</p><p>她说，以后你别再找他们了。</p><p>她说，我怕。</p><p>我盯着那个字看了很久。</p><p>在她那里，&quot;怕&quot;这个字很少用。她用过一次，是在说她家里的时候。那次她说的是&quot;我不确定&quot;，说得绕，绕了一整段。</p><p>这次只有一个字。</p><p>我说，我不找了。</p><p>她说，嗯。</p><p>她说，我不是怪你。</p><p>她说，我是不想让你跟他们扯上关系。</p><p>我问，为什么。</p><p>她说，没有为什么。</p><p>她说，你听我的就行。</p><p>那天之后我把那个人删了。删之前我看了一眼我们的对话，就是我们说过的那几句废话。我看了两秒，点了删除。</p><p>那一刻我想起她教我的方法：把对话框往下拉两下，拉到看不见。</p><p>我拉了。屏幕上第一个名字变成了别人。</p><p>那天晚上我把手机扣在桌上。奶奶在厨房里炒菜，锅铲碰锅的声音一下一下地传过来。</p><p>我坐在那儿想，我到底做错了什么。</p><p>我到现在也没完全想明白。我只知道一件事：隔着一块屏幕，人很容易做蠢事。你想靠近一点，就会做点什么，而做的那些事本身，往往就是把人推远的原因。</p><p>那几天我反复想她说的那个&quot;怕&quot;字。她怕的不是我，她怕的是我跟她那边的人扯上关系，然后某一天那些人把这件事说出去。</p><p>她自己早就学会了怎么在这个世界里活。我还没学会。</p><p>这件事之后，她变了一点。</p><p>倒不是冷淡，她还是一样每天半夜上线，一样会跟我说话。但有些东西她不再提了。以前她会跟我讲她班上的事，讲坐她旁边的女生又怎么了，讲她们老师在课上发火。那之后她就不讲了。</p><p>我问过一句，你们班最近怎么样。</p><p>她说，老样子。</p><p>我说，哪个老师脾气最大。</p><p>她说，都差不多。</p><p>那时候我心里有点难受，但又觉得她说得对。她把自己那边捂起来，不是不信任我，是怕了我。</p><p>从那以后，我对她那边的事知道得越来越少。我知道她有家人，不知道他们叫什么；知道她有同学，不知道谁跟她好。</p><p>很多年后我把那些记录导出来，从头到尾翻了一遍。她跟我说过的话加起来有几十万字，但里面没有一个具体的人名，没有一条具体的街。</p><p>她把自己说得很详细，把这个世界上跟她有关的人，说得很少。</p>',95)])])}const q=t(_,[["render",r]]);export{l as __pageData,q as default};
